function OverseaRenovaMainDialog:InitEnv()
    if self.CommonAestheticsNode then
        local env = CfUtils.GetLuaScr(self.CommonAestheticsNode,CommonAestheticsNodePath)
        if env then
            self.commonAestheticsEnv = env
        end
    end

    self.tabTagEnv = {}


    local allVos = CfUtils.GetCf(AutoIds.IdSetting4110, "MaidCoffeeRenovateTypeVo", true)
    table.sort(allVos,function(a,b) return a.sort < b.sort  end)
    for i, v in pairs(allVos) do
        local cacheGo
        local callBack
        if v.isSuit then
            cacheGo = self.MainTag
            callBack = function(delegate) self:OnSuitTagClick(delegate) end
        else
            local go = CS.UnityEngine.GameObject.Instantiate(self.OverseaRenovaTagNode1.gameObject)
            if go then
                KTool.SetParent(go,self.PartTags.gameObject,false)
                cacheGo = go
            end
            callBack = function(delegate) self:OnPartTagClick(delegate) end
        end
        if not isNull(cacheGo) then
            local env = CfUtils.GetLuaScr(cacheGo,SuitTabPath)
            if env then
                env:SetData(v,callBack)
                table.insert(self.tabTagEnv,env)
            end
        end
    end
end

