---保存
function OverseaRenovaMainDialog:OnBtnSaveClick()
    local count = 0
    local notHaveData = {}
    for i, v in pairs(self.selectData) do
        local isHave = component:IsHaveRenovated(v.refId)
        if not isHave then
            table.insert(notHaveData,v)
        end
        local isInUse = component:IsRenovatedInUse(v.refId)
        if not isInUse then
            count = count + 1
        end
    end

    if table.count(notHaveData) > 0 then
        GameUtils.SecondConfirm
        (
                localize("当前有未购买的家具，是否前去购买？"),
                function()
                    self:OnBtnShopClick()
                end,
                function()
                    if count > 0 then
                        self:SaveRenovateData()
                    end
                end,localize("如直接保存，只会保存方案中已有的家具"),8
        )
        return
    end

    ---说明有没有保存的部件
    if count > 0 then
        self:SaveRenovateData()
    end
end

function OverseaRenovaMainDialog:SaveRenovateData()
    local saveData = {}
    local showData = {}
    local saveList = component:GetSaveCattyRenovatedList()
    local avatarsIds
    for i, v in pairs(saveList) do
        local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
        local type = vo.furnitureType
        local id = v
        if self.selectData[type] then
            local isHave = component:IsHaveRenovated(self.selectData[type].furnitureId)
            if isHave then
                id = self.selectData[type].furnitureId
                vo = MaidCoffeeUtils.GetRenovateInfoVo(id)
            end
        end
        table.insert(saveData,tostring(id))
        if isNull(avatarsIds) then
            avatarsIds = id
        else
            avatarsIds = table.concat({avatarsIds,",",id})
        end
        showData[type] = vo
    end

    GameUtils.Request(Interfaces.MaidCoffeeAvatarSave,{avatars = tostring(avatarsIds) },function(request,response)
        if checkNumber(response.errCode) == 0 then
            GameUtils.Toast(localize("保存成功"))
            component:UpdateSaveRenovatedList(saveData)
            local vos = self.isSuit and self.suitVos or self.partVos
            local listView = self.isSuit and self.SuitScrollView or self.PartScrollView
            GameUtils.ReloadData(listView, table.count(vos))
            self.selectData = {}
            self.curCellIndex = nil
            self:RefreshBtnState()
            Events.Broadcast(MaidCoffeeConstants.EventNames.ChangeRenovateSuit,showData,true,nil,true)
        end
    end )
end

---购买
function OverseaRenovaMainDialog:OnBtnShopClick()
    if not isNull(self.selectSuitVo) then
        if checkNumber(self.selectSuitVo.isDirect) == 0 then
            if table.count(self.buyData) > 0 then
                UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaRenovaListDialog,parameters = {data = self.selectData,suitVo = self.selectSuitVo,cb = function()
                    self:OnBuySuccess()
                end}})
            end
        else
            local OverseaStoreUtils = import('Game.OverseaStore.OverseaStoreUtils')
            local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
            
            self.controller:SetExtraArgument(tostring(self.selectSuitVo.refId))
            self:SetSceneStatus(false)
            
            OverseaStoreUtils.OpenStore(OverseaStoreConstants.StoreType.RenovateShop , {{id =  Constants.UITypeIds.OverseaRenovaMainDialog}})
        end
    else
        if table.count(self.buyData) > 0 then
            UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaRenovaListDialog,parameters = {data = self.selectData,suitVo = self.selectSuitVo,cb = function()
                self:OnBuySuccess()
            end}})
        end
    end
end

function OverseaRenovaMainDialog:SetSceneStatus(status)
    local vo = MaidCoffeeUtils.GetMaidCoffeeSettingVo()
    ---@type SceneInstance
    local sceneInstance = SceneManagement:GetInstance():GetSceneInstance(vo.sceneId)
    if status then
        SceneManagement:GetInstance():SetActive(Constants.IdSceneSetting45, false)
        sceneInstance:Enable()
    else
