---套餐点击
function OverseaRenovaMainDialog:OnSuitTagClick(delegate)
    if not isNull(self.curEnv) then
        self.curEnv:SetTagStatus(false)
    end

    self.isSuit = true
    self.curEnv = delegate
    self.curCellIndex = nil
    self:SetScrollViewState(true)
    self.suitVos = self:GetSuitVos()
    if not self.SuitScrollView.IsListViewInit then
        self.SuitScrollView:InitGridView(#self.suitVos, Bind(self, self.OnSuitGetItemByIndex))
    else
        GameUtils.ReloadData(self.SuitScrollView, table.count(self.suitVos))
    end
    Events.Broadcast(MaidCoffeeConstants.EventNames.RenovateChange,self.curEnv.data)
end

function OverseaRenovaMainDialog:OnSuitGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if #self.suitVos < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(SuitCell)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,SuitCellPath)
        if env then
            local data = self.suitVos[index + 1]
            if not isNull(self.selectSuitVo) and self.selectSuitVo.refId == data.refId then
                self.curCellIndex = index + 1
                env:SetSelectStatus(true)
            else
                env:SetSelectStatus(false)
            end

            local furnitureId
            if not isNull(self.selectSuitId) and data.refId == checkNumber(self.selectSuitId)  then
                furnitureId = self.selectSuitId
                self.selectSuitId = nil
            end
            env:SetCallBack(Bind(self,self.OnRenovateSuitCellClick),Bind(self,self.OnSuitBuyClick),index + 1)
            env:RefreshSuitShow(data,furnitureId)
        end
    end
    return cell
end

function OverseaRenovaMainDialog:OnSuitBuyClick(vo)
    local tempData = {}
    for i, v in pairs(vo.furnitureIds) do
        local tempVo = MaidCoffeeUtils.GetRenovateInfoVo(v)
        tempData[tempVo.furnitureType] = tempVo
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaRenovaListDialog,parameters = {data = tempData,suitVo = vo,cb = function()
        self:OnBuySuccess()
    end}})
end

--TODO  这里如果直购的套装不卖了  就要判定一下玩家有没有这个套装  如果没有 就要隐藏掉
function OverseaRenovaMainDialog:GetSuitVos()
    local suitVos = CfUtils.GetCf(AutoIds.IdSetting4113, "MaidCoffeeRenovateSuitVo", true)
    local data = {}
    for i, v in pairs(suitVos) do
        local isHave = component:IsHaveRenovated(v.refId)
        if v.isDirect == 1 and not isHave then
            local isInProduct = MaidCoffeeUtils.IsInMallRenovateShop(v.refId)
            if isInProduct then
               table.insert(data,v)
            end
        else
            table.insert(data, v)
        end
    end

    return data
end

---部件点击
function OverseaRenovaMainDialog:OnPartTagClick(delegate)
    if not isNull(self.curEnv) then
        self.curEnv:SetTagStatus(false)
    end

    if not isNull(self.selectSuitVo) then
        if checkNumber(self.selectSuitVo.isDirect) == 1 then
            self.selectData = {}
            self.selectIndexData = {}
        end
    end

    self.isSuit = false
    self.curEnv = delegate
    self.curCellIndex = nil
    self:SetScrollViewState(false)
    self.partVos = self:GetPartVosByType(self.curEnv.data.furnitureType)
    if not self.PartScrollView.IsListViewInit then
        self.PartScrollView:InitGridView(#self.partVos, Bind(self, self.OnPartGetItemByIndex))
    else
        GameUtils.ReloadData(self.PartScrollView, table.count(self.partVos))
    end
    Events.Broadcast(MaidCoffeeConstants.EventNames.RenovateChange,self.curEnv.data)
    self:RefreshBtnState(false)
end

function OverseaRenovaMainDialog:OnPartGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if #self.partVos < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(SuitCell)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,SuitCellPath)
        if env then
            local data = self.partVos[index + 1]
            env:RefreshPartShow(data)
            if not isNull(self.selectData) and self.selectData[data.furnitureType] and self.selectData[data.furnitureType].refId == data.refId then
                self.selectIndexData[data.furnitureType] = index + 1
                env:SetSelectStatus(true)
            else
                env:SetSelectStatus(false)
            end
            env:SetCallBack(Bind(self,self.OnRenovatePartCellClick),Bind(self,self.OnPartBuyClick),index + 1)
        end
    end
    return cell
end

function OverseaRenovaMainDialog:OnPartBuyClick(vo)
    local tempData = {}
    tempData[vo.furnitureType] = vo
    UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaRenovaListDialog,parameters = {data = tempData,suitVo = nil,cb = function()
        self:OnBuySuccess()
    end}})
end

function OverseaRenovaMainDialog:OnRenovateSuitCellClick(delegate)
    if not isNull(self.curCellIndex) then
        if self.curCellIndex == delegate.index then
            return
        end
        local lastItem = self.SuitScrollView:GetShownItemByItemIndex(self.curCellIndex - 1)
        if lastItem then
            local env = CfUtils.GetLuaScr(lastItem,SuitCellPath)
            if env then
                env:SetSelectStatus(false)
            end
        end
    end

    self.curCellIndex = delegate.index
    local furnitureIds = delegate.data.furnitureIds
    local isHaveSuit = component:IsHaveCattySuit(furnitureIds)

    if not isHaveSuit then
        self.selectSuitVo = delegate.data
    end

    for i, v in pairs(furnitureIds) do
        local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
        self.selectData[vo.furnitureType] = vo
    end

    if checkNumber(delegate.data.isDirect)== 0 then
        self:RefreshBtnState(false)
    else
        self:RefreshBtnState(true,isHaveSuit,delegate.data.id)
    end

    Events.Broadcast(MaidCoffeeConstants.EventNames.ChangeRenovateSuit,self.selectData,true)
end

function OverseaRenovaMainDialog:OnRenovatePartCellClick(delegate)
    if not isNull(self.curCellIndex) then
        if self.curCellIndex == delegate.index then
            return
        end

        local lastItem = self.PartScrollView:GetShownItemByItemIndex(self.curCellIndex - 1)
        if lastItem then
            local env = CfUtils.GetLuaScr(lastItem,SuitCellPath)
            if env then
                env:SetSelectStatus(false)
            end
        end
    else
        local index = self.selectIndexData[delegate.data.furnitureType]
        if index == delegate.index then return end
        if not isNull(index) then
            local lastItem = self.PartScrollView:GetShownItemByItemIndex(index - 1)
            if lastItem then
                local env = CfUtils.GetLuaScr(lastItem,SuitCellPath)
                if env then
                    env:SetSelectStatus(false)
                end
            end
        end
    end
    
    self.curCellIndex = delegate.index
    local data = delegate.data
    if self.selectSuitVo then
        local isHaveSuit = component:IsHaveCattySuit(self.selectSuitVo.furnitureIds)
        if not isHaveSuit then
            if self.selectSuitVo.type == 0 or checkNumber(self.selectSuitVo.isDirect) == 1 then
                self.selectData = {}
                self.selectIndexData = {}
            end
        end
    end
    if  self.selectData[data.furnitureType] and self.selectData[data.furnitureType].refId == data.refId then
        return
    else
        self.selectData[data.furnitureType] = data
        self.selectIndexData[data.furnitureType] = delegate.index
        self.selectSuitVo = nil
    end
    if not isNull(self.curEnv) then
        self.curEnv:RefreshNewTag()
    end
    self:RefreshBtnState(false)
    Events.Broadcast(MaidCoffeeConstants.EventNames.ChangeRenovateSuit,self.selectData,false,data.furnitureType)
end


function OverseaRenovaMainDialog:RefreshBtnState(isDirect, isHaveSuit,suitId)
    KTool.SetActive(self.CurrencyPurchase.gameObject,not isDirect)
    KTool.SetActive(self.DirectPurchase.gameObject,checkBool(isDirect))
    self.buyData = {}
    if isDirect then
        local isHave = component:IsHaveCattySuitBySuitId(suitId)
        if not isHave then
            CfUtils.SetUISwitchImage(self.ImgSymbol,2)
        else
            local suitVo = MaidCoffeeUtils.GetSuitRenovateVo(suitId)
            if not isNull(suitVo) then
                local furnitureIds = suitVo.furnitureIds
                local isUse = component:IsSuitInUse(furnitureIds)
                if not isUse then
                    CfUtils.SetUISwitchImage(self.ImgSymbol,2)
                else
                    CfUtils.SetUISwitchImage(self.ImgSymbol,1)
                end
            end
        end

        KTool.SetActive(self.BtnShop.gameObject,not isHaveSuit)
        return
    end
    KTool.SetActive(self.BtnShop.gameObject,true)
    local count = 0
    for i, v in pairs(self.selectData) do
        local isHave = component:IsHaveRenovated(v.refId)
        if not isHave then
            table.insert(self.buyData,v)
        end
        local isInUse = component:IsRenovatedInUse(v.refId)
        if not isInUse then
            count = count + 1
        end
    end

    CfUtils.SetUISwitchImage(self.ImgSymbol,count > 0 and 2 or 1)

    local num = table.count(self.buyData)
    CfUtils.SetActive(self.Content.gameObject,num > 0)
    if num > 0 then
        for _, animationState in pairs(self.RedPointNode) do
            if animationState.name == "OverseaRenovaMainDialog_Shop_RedPoint" then
                animationState.time = 0
                animationState.enabled = false
                self.RedPointNode:Sample()
            end
        end
        self.RedPointNode:Play("OverseaRenovaMainDialog_Shop_RedPoint")
        CfUtils.FillText(self.SelectNum,num)
    end
end
---click end------------------------------------------------------------------------------------------------------------
function OverseaRenovaMainDialog:GetPartVosByType(type)
    local data = {}
    local allVos =  CfUtils.GetCf(AutoIds.IdSetting4111, "MaidCoffeeRenovateInfoVo", true)
    for i, v in pairs(allVos) do
        if v.furnitureType == type then
            local IsHaveRenovated = component:IsHaveRenovated(v.furnitureId)
            if IsHaveRenovated then
                table.insert(data,v)
            else
                if v.source == 1 then
                    table.insert(data,v)
                end
            end
        end
    end
    return data
end

function OverseaRenovaMainDialog:GetIndexByGoodsId(goodsId)
    goodsId = checkNumber(goodsId)
    local vos = self.isSuit and self.suitVos or self.partVos
    for index, vo in ipairs(vos) do
        if checkNumber(vo.id) == goodsId then
            return index
        end
    end
    return nil
end

--支付成功
function OverseaRenovaMainDialog:OnEventSdkEvent(parameters)
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        self:OnBuySuccess()
    end
end

function OverseaRenovaMainDialog:OnBuySuccess()
    if self.curCellIndex then
        local listView = self.isSuit and self.SuitScrollView or self.PartScrollView
        local lastItem = listView:GetShownItemByItemIndex(self.curCellIndex - 1)
        if lastItem then
            local env = CfUtils.GetLuaScr(lastItem,SuitCellPath)
            if env then
                env:RefreshIsHave()
            end
        end
    else
        local vos = self.isSuit and self.suitVos or self.partVos
        local listView = self.isSuit and self.SuitScrollView or self.PartScrollView
        GameUtils.ReloadData(listView, table.count(vos))
    end
    self:RefreshBtnState()
end

return OverseaRenovaMainDialog